// apps/cli/tw/args.ts
function parseArgs(argv) {
  const args = argv.slice(2);
  const result = {
    command: args[0] ?? "",
    positional: [],
    flags: {},
    raw: args
  };
  let i = 1;
  while (i < args.length) {
    const arg = args[i];
    if (arg.startsWith("--")) {
      const key = arg.slice(2);
      const next = args[i + 1];
      if (next && !next.startsWith("--")) {
        result.flags[key] = next;
        i += 2;
      } else {
        result.flags[key] = true;
        i++;
      }
    } else if (arg.startsWith("-") && arg.length > 1) {
      const key = arg.slice(1);
      const next = args[i + 1];
      if (next && !next.startsWith("-")) {
        result.flags[key] = next;
        i += 2;
      } else {
        result.flags[key] = true;
        i++;
      }
    } else {
      if (!result.subcommand) {
        result.subcommand = arg;
      } else {
        result.positional.push(arg);
      }
      i++;
    }
  }
  return result;
}
var ANSI2 = {
  reset: "\x1B[0m",
  bold: "\x1B[1m",
  dim: "\x1B[2m",
  red: "\x1B[31m",
  green: "\x1B[32m",
  yellow: "\x1B[33m",
  blue: "\x1B[34m",
  magenta: "\x1B[35m",
  cyan: "\x1B[36m",
  white: "\x1B[37m",
  gray: "\x1B[90m"
};
var supportsColor2 = typeof process !== "undefined" && process.stdout?.isTTY && !process.env.NO_COLOR;
function paint(color, text) {
  if (!supportsColor2) return text;
  return `${color}${text}${ANSI2.reset}`;
}
var colors = {
  red: (s) => paint(ANSI2.red, s),
  green: (s) => paint(ANSI2.green, s),
  yellow: (s) => paint(ANSI2.yellow, s),
  blue: (s) => paint(ANSI2.blue, s),
  magenta: (s) => paint(ANSI2.magenta, s),
  cyan: (s) => paint(ANSI2.cyan, s),
  white: (s) => paint(ANSI2.white, s),
  gray: (s) => paint(ANSI2.gray, s),
  bold: (s) => paint(ANSI2.bold, s),
  dim: (s) => paint(ANSI2.dim, s)
};

